# Cópia congelada das regras de memorial/redes.py (de_campos_antigos e campos_antigos): a migração não pode
# depender do código do app, que muda com o tempo.
PREFIXADAS = "tiktok|linkedin|x|youtube|threads|kwai|pinterest|snapchat|telegram|twitch|github|behance"


def _ler(instagram, facebook):
    lista = []
    instagram = (instagram or "").strip()
    facebook = re.sub(r"^(https?://)?(www\.|m\.)?facebook\.com/", "", (facebook or "").strip(), flags=re.I)
    if instagram:
        lista.append(("instagram", instagram))
    prefixada = re.fullmatch(rf"({PREFIXADAS})/([^/]+)", facebook)
    outra = re.fullmatch(r"outra/(.+)", facebook)
    if prefixada:
        lista.append((prefixada.group(1), prefixada.group(2)))
    elif outra:
        lista.append(("outra", outra.group(1)))
    elif facebook:
        lista.append(("facebook", facebook))
    return lista


def campos_para_redes(apps, schema_editor):
    Aluno = apps.get_model("memorial", "Aluno")
    RedeSocial = apps.get_model("memorial", "RedeSocial")
    novas = []
    for aluno in Aluno.objects.exclude(instagram="", facebook="").only("pk", "instagram", "facebook").iterator():
        for ordem, (rede, usuario) in enumerate(_ler(aluno.instagram, aluno.facebook)):
            novas.append(RedeSocial(aluno_id=aluno.pk, rede=rede, usuario=usuario[:100], ordem=ordem))
    RedeSocial.objects.bulk_create(novas, batch_size=500)


def redes_para_campos(apps, schema_editor):
    """Volta ao formato que o frontend atual grava: o primeiro Instagram e a primeira das outras redes."""
    Aluno = apps.get_model("memorial", "Aluno")
    RedeSocial = apps.get_model("memorial", "RedeSocial")
    por_aluno = {}
    for r in RedeSocial.objects.order_by("aluno_id", "ordem", "id"):
        por_aluno.setdefault(r.aluno_id, []).append((r.rede, r.usuario))
    for aluno_id, redes in por_aluno.items():
        instagram = next((u for rede, u in redes if rede == "instagram"), "")
        outra = next(((rede, u) for rede, u in redes if rede != "instagram"), None)
        facebook = "" if outra is None else (outra[1] if outra[0] == "facebook" else f"{outra[0]}/{outra[1]}")
        Aluno.objects.filter(pk=aluno_id).update(instagram=instagram[:60], facebook=facebook[:100])


